import re

new_core = '''import re


def clamp(x, lo, hi):
    """Constrain x to the inclusive range [lo, hi]."""
    if lo > hi:
        lo, hi = hi, lo
    return max(lo, min(x, hi))


def is_even(n):
    """Return True when n is divisible by 2."""
    return n % 2 == 0


def split_pairs(text):
    """Parse "k=v,k=v" into [("k", "v"), ...], skipping empty segments."""
    pairs = []
    for chunk in text.split(","):
        chunk = chunk.strip()
        if not chunk:
            continue
        key, _, value = chunk.partition("=")
        pairs.append((key.strip(), value.strip()))
    return pairs


def mean(values):
    return sum(values) / len(values)


def pct(part, whole):
    return part / whole * 100


def slug(text):
    """Lowercase text and join words with single hyphens."""
    return "-".join(re.findall(r"[a-z0-9]+", text.lower()))
'''

